commits.content:
body {
    font-family: Arial, sans-serif;
    background-color: #f5f6fa;
    margin: 0;
    padding: 0;
}

header {
    background-color: #2e86de;
    color: white;
    padding: 1rem;
    text-align: center;
}

h1, h2 {
    margin: 0.5rem 0;
}

.form-section, .table-section {
    width: 80%;
    margin: 2rem auto;
    background: white;
    padding: 1.5rem;
    border-radius: 8px;
    box-shadow: 0 0 10px rgba(0,0,0,0.1);
}

.form-group {
    margin-bottom: 1rem;
}

label {
    display: block;
    font-weight: bold;
    margin-bottom: 0.3rem;
}

input[type="text"], input[type="number"], input[type="date"] {
    width: 100%;
    padding: 0.6rem;
    border: 1px solid #ccc;
    border-radius: 5px;
}

button {
    background-color: #2e86de;
    color: white;
    border: none;
    padding: 0.7rem 1.2rem;
    border-radius: 5px;
    cursor: pointer;
}

button:hover {
    background-color: #1b4f72;
}

table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 1rem;
}

th, td {
    text-align: left;
    padding: 0.8rem;
    border-bottom: 1px solid #ddd;
}

tr:hover {
    background-color: #f2f2f2;
}

.btn-edit {
    color: #0b7dda;
    text-decoration: none;
    font-weight: bold;
    margin-right: 10px;
}

.btn-edit:hover {
    text-decoration: underline;
}

.btn-delete {
    color: #e74c3c;
    text-decoration: none;
    font-weight: bold;
}

.btn-delete:hover {
    text-decoration: underline;
}
